import fs from 'fs';
import path from 'path';

const fixturesDir = path.join(process.cwd(), 'tests/fixtures');
if (!fs.existsSync(fixturesDir)) {
  fs.mkdirSync(fixturesDir, { recursive: true });
}

// 1. Static GIF87a (2x2 Red)
// Header (6): GIF87a
// Screen Descriptor (7): 02 00 02 00 80 00 00 (2x2, GCT 2 colors)
// GCT (6): FF 00 00 (Red), 00 FF 00 (Green)
// Image Descriptor (10): 2C 00 00 00 00 02 00 02 00 00
// Image Data: 02 (min code size 2) 02 (sub-block size 2) 44 04 (LZW data) 00 (terminator)
// Trailer: 3B
const gif87aBytes = new Uint8Array([
  0x47, 0x49, 0x46, 0x38, 0x37, 0x61, // GIF87a
  0x02, 0x00, 0x02, 0x00, 0x80, 0x00, 0x00, // 2x2, GCT
  0xff, 0x00, 0x00, 0x00, 0xff, 0x00, // GCT: Red, Green
  0x2c, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00, // Image Descriptor
  0x02, 0x02, 0x44, 0x01, 0x00, // LZW Table & Data
  0x3b, // Trailer
]);
fs.writeFileSync(path.join(fixturesDir, 'sample-87a.gif'), gif87aBytes);

// 2. Static GIF89a (2x2 Green)
const gif89aBytes = new Uint8Array([
  0x47, 0x49, 0x46, 0x38, 0x39, 0x61, // GIF89a
  0x02, 0x00, 0x02, 0x00, 0x80, 0x00, 0x00, // 2x2, GCT
  0x00, 0xff, 0x00, 0xff, 0x00, 0x00, // GCT: Green, Red
  0x2c, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00, // Image Descriptor
  0x02, 0x02, 0x44, 0x01, 0x00,
  0x3b,
]);
fs.writeFileSync(path.join(fixturesDir, 'sample-89a.gif'), gif89aBytes);

// 3. Transparent GIF89a (2x2 with transparent pixel index 0)
// Graphic Control Extension: 21 F9 04 01 00 00 00 00 (transparent color flag = 1, transparent index = 0)
const transparentGifBytes = new Uint8Array([
  0x47, 0x49, 0x46, 0x38, 0x39, 0x61, // GIF89a
  0x02, 0x00, 0x02, 0x00, 0x80, 0x00, 0x00, // 2x2, GCT
  0x00, 0x00, 0x00, 0xff, 0x00, 0x00, // GCT: Black (index 0 - transparent), Red (index 1)
  0x21, 0xf9, 0x04, 0x01, 0x00, 0x00, 0x00, 0x00, // GCE: transparent index 0
  0x2c, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00, // Image Descriptor
  0x02, 0x02, 0x44, 0x01, 0x00,
  0x3b,
]);
fs.writeFileSync(path.join(fixturesDir, 'sample-transparent.gif'), transparentGifBytes);

// 4. Animated GIF89a (2 Frames: Frame 0 = Red, Frame 1 = Blue)
// Netscape Loop Extension + Frame 0 (Red) + Frame 1 (Blue)
const animatedGifBytes = new Uint8Array([
  0x47, 0x49, 0x46, 0x38, 0x39, 0x61, // GIF89a
  0x02, 0x00, 0x02, 0x00, 0x81, 0x00, 0x00, // 2x2, GCT with 4 colors
  0xff, 0x00, 0x00, // Color 0: Red
  0x00, 0x00, 0xff, // Color 1: Blue
  0x00, 0xff, 0x00, // Color 2: Green
  0xff, 0xff, 0xff, // Color 3: White
  // Application Extension (Netscape 2.0 loop)
  0x21, 0xff, 0x0b, 0x4e, 0x45, 0x54, 0x53, 0x43, 0x41, 0x50, 0x45, 0x32, 0x2e, 0x30, 0x03, 0x01, 0x00, 0x00, 0x00,
  // --- Frame 0 (All Red, color index 0) ---
  0x21, 0xf9, 0x04, 0x00, 0x0a, 0x00, 0x00, 0x00, // GCE: 100ms delay
  0x2c, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00, // Image Descriptor (2x2)
  0x02, 0x02, 0x44, 0x01, 0x00, // Pixels: index 0 (Red)
  // --- Frame 1 (All Blue, color index 1) ---
  0x21, 0xf9, 0x04, 0x00, 0x0a, 0x00, 0x00, 0x00, // GCE: 100ms delay
  0x2c, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x02, 0x00, 0x00, // Image Descriptor (2x2)
  0x02, 0x02, 0x4c, 0x01, 0x00, // Pixels: index 1 (Blue)
  0x3b, // Trailer
]);
fs.writeFileSync(path.join(fixturesDir, 'sample-animated.gif'), animatedGifBytes);

// 5. Corrupted GIF (Valid header but truncated stream)
const corruptedGifBytes = new Uint8Array([0x47, 0x49, 0x46, 0x38, 0x39, 0x61, 0x02, 0x00, 0x02]);
fs.writeFileSync(path.join(fixturesDir, 'corrupted.gif'), corruptedGifBytes);

console.log('GIF test fixtures successfully written.');
